import casadi as ca
import numpy as np
import matplotlib.pyplot as plt



# --- Example track boundaries (replace with your data)
left = np.array([[0,0],[0,3],[2,5],[3,5]])
right = np.array([[0,0],[1,2],[3,4],[4,4]])
N = left.shape[0]

# Compute midpoints and half-widths
mid = (left + right) / 2
half_width = 0.5 * np.linalg.norm(right - left, axis=1)

# Tangent vectors along the track
tangent = np.zeros_like(mid)
tangent[1:-1] = mid[2:] - mid[:-2]
tangent[0] = mid[1] - mid[0]
tangent[-1] = mid[-1] - mid[-2]
tangent /= np.linalg.norm(tangent, axis=1, keepdims=True)

# Normal vectors (pointing roughly left)
normal = np.column_stack([-tangent[:,1], tangent[:,0]])

# === Decision variables: lateral offset d along normal ===
d = ca.MX.sym('d', N)

# Racing line coordinates
x = mid[:,0] + d * normal[:,0]
y = mid[:,1] + d * normal[:,1]

# --- Objective: minimize curvature squared + smoothness
cost = 0
for i in range(1, N-1):
    dx1 = x[i] - x[i-1]
    dy1 = y[i] - y[i-1]
    dx2 = x[i+1] - x[i]
    dy2 = y[i+1] - y[i]
    curvature = (dx1*dy2 - dy1*dx2) / ((dx1**2 + dy1**2 + 1e-6)**1.5)
    cost += curvature**2
cost += 0.1 * ca.sumsqr(ca.diff(d))

# --- Constraints: stay between left and right boundaries
g = []
for i in range(N):
    g.append(d[i])         # >= -half_width
    g.append(-d[i])        # >= -half_width (symmetrical)

# --- Build NLP
nlp = {'x': d, 'f': cost, 'g': ca.vertcat(*g)}

solver = ca.nlpsol('solver', 'ipopt', nlp, {
    'ipopt.print_level': 0,
    'print_time': 0
})

# Initial guess: centered
sol = solver(x0=np.zeros(N),
             lbg=[-half_width[i] for i in range(N)] + [ -half_width[i] for i in range(N)],
             ubg=[ half_width[i] for i in range(N)] + [  half_width[i] for i in range(N)])

d_opt = np.array(sol['x']).flatten()
racing = mid + d_opt[:,None] * normal

# --- Print racing line points
print("\nRacing line points (x, y):")
for i, point in enumerate(racing):
    print(f"Point {i}: ({point[0]:.6f}, {point[1]:.6f})")


